/** 格式化数字（千分位） */
function num(v, digits = 0) {
  if (v === null || v === undefined || Number.isNaN(v)) return '—';
  return Number(v).toLocaleString('zh-CN', {
    minimumFractionDigits: digits, maximumFractionDigits: digits,
  });
}
function pct(v, digits = 1) {
  if (v === null || v === undefined || Number.isNaN(v)) return '—';
  return `${Number(v).toFixed(digits)}%`;
}
function ms(v) {
  if (!v) return '—';
  return v >= 1000 ? `${(v / 1000).toFixed(2)} s` : `${v} ms`;
}

/** 分级标签 */
function levelBadge(level) {
  const map = {
    L1: ['badge-success', 'L1 · 模型推理'],
    L2: ['badge-warning', 'L2 · 商品级降级'],
    L3: ['badge-neutral', 'L3 · 不可预测'],
  };
  const [cls, text] = map[level] || map.L3;
  return `<span class="badge ${cls}">${text}</span>`;
}

/** 置信度标签 */
function confBadge(level) {
  const map = {
    L1: ['badge-success', '高'],
    L2: ['badge-warning', '中'],
    L3: ['badge-neutral', '低'],
  };
  const [cls, text] = map[level] || map.L3;
  return `<span class="badge ${cls}">${text}</span>`;
}

/** 状态徽标 */
function statusBadge(status, errorCode) {
  if (status === 'succeeded') return `<span class="badge badge-success">${ICONS.check}已完成</span>`;
  if (status === 'running') return `<span class="badge badge-info"><span class="dot dot-info dot-pulse"></span>运行中</span>`;
  if (status === 'failed') return `<span class="badge badge-danger">${ICONS.x}失败 · ${errorCode || ''}</span>`;
  return `<span class="badge badge-neutral">未知</span>`;
}

