/** 初始化页面公共部分 */
function initShell(active, opts = {}) {
  renderHeader(active, opts);
  renderSidebar(active);
  renderFooter();

  // 移动端侧边栏
  const toggle = document.getElementById('sidebar-toggle');
  const sidebar = document.getElementById('sidebar');
  if (toggle && sidebar) {
    toggle.style.display = '';
    toggle.addEventListener('click', () => sidebar.classList.toggle('open'));
  }
  document.addEventListener('click', (e) => {
    if (window.innerWidth > 900) return;
    if (sidebar && !sidebar.contains(e.target) && e.target !== toggle) {
      sidebar.classList.remove('open');
    }
  });
}

/* ---------- 12. 导出（CSV，带 BOM 保证 Excel 中文不乱码） ---------- */
function exportCsv(filename, rows, headers) {
  const head = headers || Object.keys(rows[0] || {});
  const lines = [head.join(',')];
  rows.forEach((r) => {
    lines.push(head.map((h) => {
      const v = r[h];
      const s = v === null || v === undefined ? '' : String(v);
      return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    }).join(','));
  });
  // \ufeff = UTF-8 BOM（PRD NFR-COMP-05）
  const blob = new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
}
